// SQLMeshLexerInit initializes any static state used to implement SQLMeshLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewSQLMeshLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func SQLMeshLexerInit() {
	staticData := &SQLMeshLexerLexerStaticData
	staticData.once.Do(sqlmeshlexerLexerInit)
}

// NewSQLMeshLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewSQLMeshLexer(input antlr.CharStream) *SQLMeshLexer {
	SQLMeshLexerInit()
	l := new(SQLMeshLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &SQLMeshLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "SQLMeshLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

