// SQLMeshLexerSQL_BODY_MODE is the SQLMeshLexer mode.
const SQLMeshLexerSQL_BODY_MODE = 1

var _depth int

func (l *SQLMeshLexer) Action(localctx antlr.RuleContext, ruleIndex, actionIndex int) {
	switch ruleIndex {
	case 44:
		l.LPAREN_Action(localctx, actionIndex)

	case 45:
		l.RPAREN_Action(localctx, actionIndex)

	default:
		panic("No registered action for: " + fmt.Sprint(ruleIndex))
	}
}

func (l *SQLMeshLexer) LPAREN_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 0:
		_depth++

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
func (l *SQLMeshLexer) RPAREN_Action(localctx antlr.RuleContext, actionIndex int) {
	switch actionIndex {
	case 1:

		_depth--
		if _depth == 0 {
			l.PushMode(SQLMeshLexerSQL_BODY_MODE)
		}

	default:
		panic("No registered action for: " + fmt.Sprint(actionIndex))
	}
}
